import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {ITEMS,applySupply} from '../repertoire.js?v=5.6.0';import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero} from '../mako.js';import {legacyFrom} from '../origins.js?v=5.6.0';import {combatContext} from '../combat-reactions.js';
import {economyState,economyRegion,district,marketInfo,quoteSupply,purchaseSupply,tradeGood,commodityQuote,localNeed,fulfillNeed,buildCivic,craftSupply,RECIPES,GOODS,STAMPS,acceptShipment,routeOffer,deliverShipment,cancelShipment,encounterSalvage,awardReciprocity,gatherTradeGoods,validateEconomy,economyLegacy} from '../economy.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
const state=(chapter=24)=>({chapter,mode:'field',gold:10000,items:{},heroes:[defaultHero(0)],flags:{}});
test('all 24 regional markets have finite materials, distinct surplus and needs and no same-market resale profit',()=>{for(let r=1;r<=24;r++){const s=state(),m=marketInfo(s,r);assert.notEqual(m.exportGood,m.needGood);for(const g of GOODS){const q=commodityQuote(s,r,g.id);assert.ok(q.sell<q.buy);const gold=s.gold;for(let i=0;i<4;i++)assert.ok(tradeGood(s,r,g.id,'buy'));assert.equal(tradeGood(s,r,g.id,'buy'),false);for(let i=0;i<4;i++)assert.ok(tradeGood(s,r,g.id,'sell'));assert.equal(tradeGood(s,r,g.id,'sell'),false);assert.ok(s.gold<gold);assert.equal(economyState(s).goods[g.id],0);}}});
test('actual cross-region trade earns a bounded margin and rest or reload cannot refill quotas',()=>{const s=state(2);for(let i=0;i<4;i++)assert.ok(tradeGood(s,2,'fiber','buy'));const paid=s.gold;for(let i=0;i<4;i++)assert.ok(tradeGood(s,1,'fiber','sell'));assert.equal(s.gold-paid,76);const restored=JSON.parse(JSON.stringify(s));assert.equal(tradeGood(restored,2,'fiber','buy'),false);restored.chapter=3;assert.ok(tradeGood(restored,2,'fiber','buy'));});
test('reciprocity belongs to one district, comes from work once, and is spent explicitly',()=>{const s=state();assert.ok(awardReciprocity(s,1,'kindness',3));assert.equal(awardReciprocity(s,1,'kindness',3),false);assert.equal(district(s,2).favor,0);const tonic=ITEMS.find(x=>x.id==='tonic'),q=quoteSupply(s,1,tonic,true);assert.equal(q.favorCost,2);assert.ok(q.price<tonic.price);assert.ok(purchaseSupply(s,1,tonic,true));assert.equal(district(s,1).favor,1);assert.equal(s.items.tonic,1);assert.equal(quoteSupply(s,1,tonic,true).favorCost,0);});
test('public investment changes crafting, prices and real battle context once',()=>{const s=state();Object.assign(economyState(s).goods,{metal:20,fiber:20,glass:20});const tonic=ITEMS.find(x=>x.id==='tonic'),before=quoteSupply(s,1,tonic).price;assert.ok(buildCivic(s,1,'water'));assert.ok(quoteSupply(s,1,tonic).price<before);assert.equal(buildCivic(s,1,'water'),false);assert.ok(buildCivic(s,1,'workshop'));const old=s.economy.goods.fiber;assert.ok(craftSupply(s,1,RECIPES[0]));assert.equal(s.economy.goods.fiber,old-1);assert.ok(buildCivic(s,1,'commons'));const context=combatContext({state:s,scene:{key:'field',chapter:1,location:5}});assert.ok(context.tags.includes('grounded'));assert.ok(context.tags.includes('shelter'));const h=defaultHero(0),b=new Battle({heroes:[h],enemies:[makeEnemy('guard',1)],context});assert.equal(h.status.shield,15);h.atb=1;h.mp=0;b.command(0,'guard');assert.equal(h.mp,7);});
test('crafted supplies really execute their normal battle mechanics',()=>{const s=state();s.economy=economyState(s);s.economy.goods.glass=10;assert.ok(craftSupply(s,1,RECIPES.find(r=>r.item==='tideFlask')));const h=defaultHero(0),e=makeEnemy('predator',1),b=new Battle({heroes:[h],enemies:[e]});h.atb=1;assert.ok(applySupply(b,s.items,'tideFlask',h,e));assert.ok(e.status.wet);assert.equal(s.items.tideFlask,0);});
test('contracts consume real goods, have bounded requests, and never consume partial payment',()=>{const s=state();const n=localNeed(s,1),gold=s.gold;assert.equal(fulfillNeed(s,1),false);assert.equal(s.gold,gold);economyState(s).goods[n.id]=6;assert.ok(fulfillNeed(s,1));assert.ok(fulfillNeed(s,1));assert.equal(fulfillNeed(s,1),false);assert.equal(s.economy.goods[n.id],2);assert.equal(district(s,1).favor,6);});
test('shipments require destination and two distinct real encounters; cancel and claims are exact',()=>{const s=state(2),e=economyState(s);e.goods.fiber=4;assert.ok(acceptShipment(s,2));const q=e.shipments[0];assert.equal(deliverShipment(s,1,q.id),false);assert.equal(encounterSalvage(s,{key:'test',type:'practice'}),null);assert.ok(encounterSalvage(s,{key:'fight-a',type:'patrol',core:'flame'}));assert.equal(encounterSalvage(s,{key:'fight-a',type:'patrol'}),null);assert.equal(q.protected,1);assert.ok(encounterSalvage(s,{key:'fight-b',type:'boss',core:'tide'}));assert.equal(deliverShipment(s,2,q.id),false);assert.ok(deliverShipment(s,1,q.id));assert.equal(deliverShipment(s,1,q.id),false);assert.ok(e.stamps.includes('first-road'));assert.equal(acceptShipment(s,2),false);s.chapter=3;assert.ok(acceptShipment(s,2));const old=e.goods.fiber;assert.ok(cancelShipment(s,e.shipments[0].id));assert.equal(e.goods.fiber,old+2);});
test('trade seals are unique and lineage carries institutions, never cash, materials or local favor',()=>{const s=state();const e=economyState(s);e.stamps=STAMPS.map(x=>x.id);district(s,1).works=['water'];district(s,1).favor=20;e.goods.metal=99;const legacy=legacyFrom({...s,recruited:[0],complete:true});assert.deepEqual(legacy.trade,{stamps:e.stamps,works:1});const w=new World(data);w.newGame({originId:'sable-reed',legacy});assert.equal(w.state.gold,0);assert.deepEqual(w.state.economy.goods,{metal:0,fiber:0,glass:0});assert.deepEqual(w.state.economy.stamps,e.stamps);assert.equal(district(w.state,1).favor,0);assert.equal(purchaseSupply(w.state,1,ITEMS[0]),false);});
test('borrowed trials and active battles cannot create goods or currency',()=>{for(const mode of ['battle','trial','past']){const s=state();if(mode==='trial')s.fieldOrigins={active:{}};else if(mode==='past')s.chronicle={phase:'past'};else s.mode='battle';assert.equal(tradeGood(s,1,'metal','buy'),false);assert.equal(awardReciprocity(s,1,'bad'),false);assert.equal(gatherTradeGoods(s,1,'bad'),false);assert.equal(encounterSalvage(s,{key:'bad',type:'boss'}),null);assert.equal(s.gold,10000);}});
test('economy save validation rejects negative materials and invalid shipments',()=>{const s=state();economyState(s);assert.ok(validateEconomy(JSON.parse(JSON.stringify(s))));s.economy.goods.glass=-1;assert.throws(()=>validateEconomy(s));s.economy.goods.glass=0;s.economy.shipments=[{id:'bad',good:'metal',quantity:-2,credits:500,protected:2,destination:1,encounters:[]}];assert.throws(()=>validateEconomy(s));assert.deepEqual(economyLegacy({}),{stamps:[],works:0});});
test('World victory awards salvage once and practice cannot mint currency',()=>{const w=new World(data);w.state.mode='field';w.currentBattle={scene:w.state.scene,mission:w.mission,object:{type:'practice'}};const gold=w.state.gold;w.winBattle();assert.equal(w.state.gold,gold);w.state.mode='field';const obj={type:'patrol',bit:29,salvageCore:'tide'};w.currentBattle={scene:999,mission:w.mission,object:obj};w.winBattle();assert.equal(w.state.economy.goods.glass,1);w.state.mode='field';w.currentBattle={scene:999,mission:w.mission,object:obj};w.winBattle();assert.equal(w.state.economy.goods.glass,1);const saved=w.save(),copy=new World(data);copy.restore(saved);assert.equal(copy.state.economy.goods.glass,1);});
test('merchant spending fills a real community reserve that co-funds public services',()=>{const s=state();economyState(s).goods.glass=4;const item=ITEMS.find(x=>x.id==='tonic');assert.ok(purchaseSupply(s,1,item));assert.equal(district(s,1).reserve,2);const old=s.gold;assert.ok(buildCivic(s,1,'water'));assert.equal(old-s.gold,88);assert.equal(district(s,1).reserve,0);assert.equal(s.economy.flow.public,90);});

test('the central hub stays in Cinderfall and cannot impersonate a cargo destination as chapters advance',()=>{const w=new World(data);w.state.chapter=12;w.state.scene=226;assert.equal(economyRegion(w),1);});
